import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水泽节","description":"周易折中 - 水泽节","frontmatter":{"title":"水泽节","description":"周易折中 - 水泽节"},"headers":[],"relativePath":"zh/classics/zhezhong/066.md","filePath":"zh/classics/zhezhong/066.md"}'),h={name:"zh/classics/zhezhong/066.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="水泽节" tabindex="-1">水泽节 <a class="header-anchor" href="#水泽节" aria-label="Permalink to “水泽节”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈节序卦〉：“涣者，离也。物不可以终离，故受之以《节》。物既离散，则当节止之。《节》所以次《涣》也。为卦，泽上有水，泽之容有限，泽上置水，满则不容，为有节之象，故为《节》。”</p><p>节：亨，苦节不可贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>节，有限而止也。为卦下兑上坎，泽上有水，其容有限，故为节。节固自有亨道矣，又其体阴阳各半而二五皆阳，故其占得亨。然至于太甚，则苦矣，故又戒以不可守以为贞也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>事既有节，则能致亨通，故节有亨义。节贵适中，过则苦矣。节至于苦，岂能常也？不可固守以为常，不可贞也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖逹曰：节者，制度之名，节止之义。制事有节，其道乃亨，故曰“节亨”。节须得中为节，过苦伤于刻薄，物所不堪，不可复正，故曰“苦节不可贞也”。</li></ul><p>孔氏颖逹曰：节者，制度之名，节止之义。制事有节，其道乃亨，故曰“节亨”。节须得中为节，过苦伤于刻薄，物所不堪，不可复正，故曰“苦节不可贞也”。</p><ul><li>薛氏温其曰：节以礼，其道乃亨。过苦伤陋，不可以为正也。</li></ul><p>薛氏温其曰：节以礼，其道乃亨。过苦伤陋，不可以为正也。</p><p>象曰：泽上有水，节；君子以制数度，议德行</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽之容水有限，过则盈溢，是有节，故为节也。君子观节之象，以制立数度。凡物之大小、轻重、高下、文质，皆有数度，所以为节也。数多寡，度法制。议德行者，存诸中为德，发于外为行。人之德行当议，则中节。议谓商度求中节也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰 ：泽上有水，以堤防为节。</p></li><li><p>张氏浚曰 ：数度之制因乎人，德行之议自于已。记曰：“君子议道自己而置法以民。”盖已之所不能行，与其所不可行而强于人，谁其从之？一言尽节之道，中而已。中必自身始也。</p></li><li><p>朱氏震曰 ：泽之容水固有限量，虚则纳之，满则泄之。水以泽为节也。</p></li><li><p>郭氏雍曰 ：泽无水则为不足，泽上有水则为有馀。不足则为困，有馀则当节。理之常也。在人之节，则制数度所以节于外，议德行所以节于内也。为国为家，至于一身，其内外制节皆一也。</p></li><li><p>孔氏颖逹曰 ：数度谓尊卑礼命之多少，德行谓人才堪任之优劣。君子象节以制其礼数等差，皆使有度；议人之德行，任用皆使得宜。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>议德行，诸儒皆谓一身之德行。独孔氏谓在人之德行，于“议”字尤切，且得“爱爵禄”、“愼名器”之意。</p><p>彖曰：节 亨，刚柔分而刚得中</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>节之道，自有亨义。事有节则能亨也。又卦之才，刚柔分处，刚得中而不过，亦所以为节，所以能亨也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>赵氏玉泉曰：统观全体而刚柔适均，则刚以济柔，柔以济刚，一张一弛，惟其称也。折观二体而二五得中，则不失之过，不失之不及，一损一益，惟其宜也。由是以制数度而隆杀皆中，以议徳行而进反皆中，此节之所以亨也。</li></ul><p>苦节不可贞，其道穷也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>又以理言。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>节至于极而苦，则不可坚固常守其道也，穷极也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：若以苦节为正，则其道困穷。</p></li><li><p>吴氏应回曰：中节则和，否则不和。稼穑作甘，以得中央之土也；火炎上则苦，亦以焦枯之极也。刚得中而能节，乃为九五之甘；柔失中而过节，则为上六之苦。故物得中则甘，失中则苦。</p></li><li><p>俞氏琰曰：凡物过节，则苦味之过、正形之过、劳心之过思，皆谓之苦节，而苦则非通行之道，故曰其道穷也。</p></li><li><p>黄氏淳耀曰：合于中即甘即亨，失其中即苦即穷。苦与甘反，穷与亨反。</p></li></ul><p>说以行险，当位以节，中正以通</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>又以卦体卦徳言之，当位中正指五，又坎为通。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言也。内兑外坎，说以行险也。人于所说，则不知已遇艰险，则思止。方说而止，为节之义。当位以节，五居尊当位也，在泽上有节也。当位而以节主节者也，处得中正，节而能通也。中正则通，过则苦矣。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：更就二体及四五当位，重释行节得亨之义，以明苦节之穷也。</p></li><li><p>林氏希元曰：九五阳刚居尊，当位以主节于上，而所节者得其中正，是可以通行于天下。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>说以行险，先儒说义未明。葢节有阻塞难行之象，所谓险也，而其所以亨者，则以其有安适之善而无拘迫之苦，所谓说也。当位以位言，中正以徳言。当位则有节天下之权，中正则能通天下之志。此三句当依孔氏为总申彖辞之义，说则不苦而通则不穷矣。葢上文既以全卦之善言之，此又专主九五及卦徳以申之，正与渐卦同例。</p><p>天地节而四时成，节以制度，不伤财不害民</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言节道。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>推言节之道，天地有节故能成四时，无节则失序也。圣人立制度以为节，故能不伤财害民。人欲之无穷也，苟非节以制度，则侈肆至于伤财害民矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：天地以气序为节，使寒暑往来各以其序，则四时功成也。王者以制度为节，使用之有道，役之有时，则不伤财不害民也。</p></li><li><p>吴氏曰：慎曰“革”，曰“天地革而四时成”，此曰“天地节而四时成”。限止之谓节，改易之谓革。节浅而革深，节先而革后。四时举其大者言之，天地之化刻刻相节，时时相革。</p></li></ul><p>初九：不出户庭，无咎。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>户庭，户外之庭也。阳刚得正，居节之初，未可以行，能节而止者也。故其象占如此。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>户庭，户外之庭；门庭，门内之庭。初以阳在下，上复有应，非能节者也。又当节之初，故戒之。谨守至于不出户庭，则无咎也。初能固守，终或渝之；不谨于初，安能有卒？故于节之初为戒甚严也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰：阳刚在下，居得其正，当节之初，知其时未可行，故谨言谨行，至于不出户外之庭，是知节而能止者，故无咎。</li></ul><p>王氏申子曰：阳刚在下，居得其正，当节之初，知其时未可行，故谨言谨行，至于不出户外之庭，是知节而能止者，故无咎。</p><ul><li>徐氏在汉曰：坎变下一画为兑，象止。坎下流，户以节人之出入，泽以节水之出入。初不出户庭，以极其愼宻为不出，此其所以无咎。</li></ul><p>徐氏在汉曰：坎变下一画为兑，象止。坎下流，户以节人之出入，泽以节水之出入。初不出户庭，以极其愼宻为不出，此其所以无咎。</p><p>象曰：不出户庭，知通塞也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>爻辞于节之初，戒之谨守，故云“不出户庭，则无咎也”。象恐人之泥于言也，故复明之云：虽当谨守，不出户庭，又必知时之通塞也。通则行，塞则止。义当出则出矣。尾生之信，水至不去，不知通塞也。故君子贞而不谅，系辞所解独以言者，在人所节，唯言与行。节于言，则行可知。言当在先也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰 ：时有通塞，通则行，塞则止。当止即止，其知通塞之君子乎？系辞专以愼密言语说之，兑体故也。</p></li><li><p>吴氏曰 ：愼曰节，兼通塞。言犹艮之兼行止言也。初九“不出户庭”，知塞也，而兼言知通者，见其非一于止者也。二失时极则，但知塞而不知通矣。</p></li></ul><p>九二：不出门庭，凶。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>门庭，门内之庭也。九二当可行之时而失刚不正，上无应与，知节而不知通，故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>二虽刚中之质，然处阴居说而承柔，处阴不正也，居说失刚也，承柔近邪也。节之道当以刚中正，二失其刚中之德，与九五刚中正异矣。不出门庭，不之于外也，谓不从于五也。二五非阴阳正应，故不相从。若以刚中之道相合，则可以成节之功。惟其失徳失时，是以凶也。不合于五，乃不正之节也。以刚中正为节，如惩忿窒欲，损过益有馀是也；不正之节，如啬节于用，懦节于行是也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云：户庭是初爻之象，门庭是第二爻之象。</p></li><li><p>钱氏志立曰：泽所以锺水也，水始至则増其防以潴之，初九是也；水渐盛则启其窦以泄之，九二是也。二与初同道，则失其节矣。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>节卦六爻皆以泽水二体取义。泽者止水，者行。节虽以止为义，然必可以通行而不穷，乃为节之亨也。初二两爻，一在泽底，一在泽中。在泽底者，水之方潴，不出宜也；在泽中，则当有蓄泄之道，不可闭塞而不出也。兑本坎体中爻，其主也，有坎之德可以流行而变，兑则为下流之塞。二适当之，故六爻之失时未有如二者也。时应塞而塞，则为慎宻不出，虽足不窥户可也；时不应塞而塞，则为绝物自废，所谓“出门同人”者安在哉？</p><p>象曰：不出门庭，凶；失时极也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>不能上从九五刚中正之道，成节之功乃系于私昵之阴柔，是失时之至极，所以凶也。失时，失其所宜也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：水之始至泽，当塞而不当通；既至，当通而不当塞。故初九以“不出户庭”为无咎，言当塞也；九二以“不出门庭”为凶，言当通也。至是而不通，则失时而至于极。</p></li><li><p>郭氏雍曰 ：初为不当有事之地，而二以刚中居有为之位，其道不可同也。故初以“不出户庭”为知塞，而二以“不出门庭”为不知通。知塞故无咎，不知通则有失时之凶矣。</p></li></ul><p>六三：不节若，则嗟若，无咎。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>阴柔而不中正，以当节时，非能节者，故其象占如此。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>六三不中正，乘刚而临险，固宜有咎。然柔顺而和说，若能自节而顺于义，则可以无过；不然，则凶咎必至，可伤嗟也。故不节若，则嗟若，己所自致，无所归咎也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：处非其位，失节也。然能嗟其不节，则亦无咎矣。 又曰：王弼于此“无咎”又别立一例，只旧例亦可推行。但能嗟其不节，有补过之心，则亦无咎也。</p></li><li><p>又曰：王弼于此“无咎”又别立一例，只旧例亦可推行。但能嗟其不节，有补过之心，则亦无咎也。</p></li><li><p>李氏彦章曰：临之六三失临之道而既忧之，节之六三失节之道而嗟若，皆得无咎。易以补过为善者也。</p></li><li><p>郑氏汝谐曰：进乘二阳，处泽之溢，过乎中而不节者三也。知其不节而能伤嗟以自悔，其谁咎之哉？下体之极，极则当变，故发此义。</p></li><li><p>丰氏寅初曰：处兑之极，水溢泽上，说于骄侈，不知谨节以致穷困。然其心痛悔形于悲叹，能悔则有改过之㡬，是犹可以无咎也。</p></li></ul><p>象曰：不节之嗟，又谁咎也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>此“无咎”与诸爻异，言无所归咎也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>节则可以免过，而不能自节以致可嗟，将谁咎乎？</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>沈氏一贯曰 ：王介甫、程沙随谓能嗟怨自治，亦无咎。嗟与戚、嗟若之嗟同，“又谁咎”与“出门”、“同人”之象同。</p></li><li><p>何氏楷曰 ：诸卦爻辞言“无咎”者九十有九，多补过之辞。解三爻传“又谁咎”语虽与此同，然爻辞未尝有“无咎”字。</p></li></ul><p>六四：安节亨。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>柔顺得正，上承九五，自然有节者也。故其象占如此。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>四顺承九五刚中正之道，是以中正为节也。以阴居阴，安于正也。当位为有节之象，下应于初。四坎体水也，水上溢为无节，就下有节也。如四之义，非强节之，安于节者也，故能致亨。节以安为善，强守而不安，则不能当，岂能亨也？</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：六三失位而处兑泽之极，是乃溢而不节；六四当位而顺承九五之君，故为安节。案六四以柔正承五，故曰“安节”。安与勉对，葢凡其制节谨度，皆循乎成法而安行，非勉强以为节者也。于象居坎之下，水之下流也，柔正为水流平地、安澜之象。</li></ul><p>象曰：安节之亨，承上道也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>四能安节之义非一，象独举其重者。上承九五刚中正之道以为节，足以亨矣。馀善亦不出于中正也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>钱氏一本曰 ：中正之通在五，四以近承不以徒止为功，更以通行为道，故曰“承上道也”。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>节曰“亨”为九五中正以通也。而亨于四言之者，五者水之源也，四者水之流也。水之通在流，承上之源而布之者也。</p><p>九五：甘节，吉；往有尚。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>所谓当位以节，中正以通者也。故其象占如此。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>九五刚中正，居尊位，为节之主，所谓当位以节，中正以通者也。在己则安行，天下则说从，节之甘美者也，其吉可知。以此而行，其功大矣，故往则有可嘉尚也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：当位居中，为节之主，不失其中，不伤财不害民之谓也。为节而不苦，非甘而何？术斯以往，往有尚也。</p></li><li><p>朱子语类云：甘便对那苦。甘节与“礼之用和为贵”相似。</p></li><li><p>赵氏汝梅曰：咸苦酸辛，味之偏；甘，味之中也。甘受和，和者节味之偏而适其中。行之以甘，人不吾病而事以成，节之吉也。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>水之止者苦，积泽为卤是也；其流者甘，山下出泉是也。五为坎主，水之源也。在井为冽，取其不泥；在节为甘，取其不苦也。</p><p>象曰：甘节之吉，居位中也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>既居尊位，又得中道，所以吉而有功。节以中为贵，得中则正矣，正不能尽中也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：节贵乎中。当节而不节，则六三有“不节之嗟”；过于节，则上六有“苦节之凶”。惟九五“甘节”而吉者，盖居位之中，当位以节，无过无不及也。</li></ul><p>上六：苦节贞凶，悔亡。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>居节之极，故为苦节。既处过极，故虽得正而不免于凶。然礼奢宁俭，故虽有悔而终得亡之也。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>上六居节之极，节之苦者也。居险之极，亦为苦义。固守则凶，悔则凶亡，悔损过从中之谓也。节之悔亡与他卦之悔亡辞同而义异也。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>干氏宝曰：彖称“苦节不可贞”，在此爻也，故曰“贞凶”。</p></li><li><p>孔氏颖逹曰：上六处节之极，过节之中节，不能甘以至于苦，故曰“苦节”也。若以苦节施人，则是正道之凶；若以苦节脩身，则俭约无妄，可得亡悔。</p></li><li><p>吕氏大临曰：上六居节之极，其节己甚，苦节者也。用过乎节，物所不堪守，是不变物穷必乖，故曰“贞凶”。礼奢宁俭，未害乎义，故曰“悔亡”。</p></li><li><p>胡氏炳文曰：五位中，故为甘；上位极，故为苦。彖曰“节亨”，五以之；曰“苦节不可贞”，上以之。</p></li><li><p>来氏知德曰：无甘节之吉，故贞凶；无不节之嗟，故悔亡。</p></li></ul><p>象曰：苦节贞凶，其道穷也</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>节既苦而贞，固守之则凶，盖节之道至于穷极矣。</p><h3 id="集说-17" tabindex="-1">集说 <a class="header-anchor" href="#集说-17" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰 ：愼曰爻言“苦节贞凶”，彖言“苦节不可贞”。惟其贞凶，是以不可贞也。故彖、象传皆以其道穷也释之。</li></ul><p>总论</p><ul><li><p>丘氏富国曰：彖传“当位以节”，故节之六爻以当位为善，不当位为不善。若以两爻相比者观之，则又各相比而相反。初与二比，初不出户庭则无咎，二不出门庭则凶，二反乎初者也；三与四比，四柔得正则为安节，三柔不正则为不节，三反乎四者也；五与上比，五得中则为节之甘，上过中则为节之苦，上反乎五者也。</p></li><li><p>陆氏振奇曰：观下卦“通塞”二字，上卦“甘苦”二字，可以知节道矣。通处味甘，塞处味苦；塞极必溃，故三受焉；甘失反苦，故上受焉。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>下卦为泽为止，故初二皆曰“不出”；三则泽之止而溢也。上卦为水为流，故四曰“安”而五曰“甘”，上则水之流而竭也。通塞甘苦，皆从泽水取义，陆氏之说得之矣。</p>',137)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
